<?php
declare(strict_types=1);session_start();if(empty($_SESSION['user_id'])){header('Location: login.php');exit;}
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verification Test</title><style>body{margin:0;background:#f6f7fb;font-family:system-ui}.box{max-width:650px;margin:40px auto;background:#fff;padding:28px;border-radius:18px;border:1px solid #ddd}input,select{width:100%;padding:12px;margin:7px 0 14px;box-sizing:border-box}button{background:#6d35e8;color:#fff;border:0;border-radius:9px;padding:12px 18px;font-weight:700}.qr{margin:20px auto;text-align:center}</style></head><body><div class="box"><h1>Verification Test Console</h1><p>Create a test verification request as if QuiGo or Adizzle were calling the API.</p><label>App</label><select id="app"></select><label>User reference</label><input id="user" value="test-user-001"><label>Purpose</label><input id="purpose" value="login"><button onclick="create()">Create QR Verification</button><div id="out"></div><div class="qr" id="qr"></div></div><script>
async function load(){let r=await fetch('index.php?route=my-apps');let j=await r.json();if(j.success)app.innerHTML=j.apps.map(a=>'<option value="'+a.id+'">'+a.name+'</option>').join('')}
async function create(){let r=await fetch('index.php?route=create-verification',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({app_id:app.value,user_reference:user.value,purpose:purpose.value,method:'qr'})});let j=await r.json();out.innerHTML='<p>'+j.message+'</p><pre>'+JSON.stringify(j,null,2)+'</pre>';if(j.qr_url){qr.innerHTML='<img alt="QR" width="260" src="https://api.qrserver.com/v1/create-qr-code/?size=260x260&data='+encodeURIComponent(j.qr_url)+'">'} }load();
</script></body></html>
